(function(){document.querySelectorAll('.p-FB-13-1').forEach(function(r){var l=r.querySelector('.launcher'),f=r.querySelector('.composer'),inp=f.querySelector('input'),log=r.querySelector('.log');function add(c,t){var li=document.createElement('li');li.className='msg '+c;li.textContent=t;log.appendChild(li);log.scrollTop=log.scrollHeight;}function set(o){r.classList.toggle('is-open',o);l.setAttribute('aria-expanded',o?'true':'false');l.setAttribute('aria-label',o?'サポートチャットを閉じる':'サポートチャットを開く');if(o)setTimeout(function(){inp.focus();},0);}l.addEventListener('click',function(){set(!r.classList.contains('is-open'));});r.addEventListener('keydown',function(e){if(e.key==='Escape'&&r.classList.contains('is-open')){set(false);l.focus();}});f.addEventListener('submit',function(e){e.preventDefault();var v=inp.value.trim();if(!v)return;add('out',v);inp.value='';setTimeout(function(){add('in','確認します。少々お待ちください。');},1000);});});})();

