(function(){document.querySelectorAll('.p-FB-14-1').forEach(function(r){var no=r.querySelector('[data-no]'),ta=r.querySelector('.ta'),dt=r.querySelector('.dt');function step(s){r.setAttribute('data-step',s);var re=s==='reason';no.classList.toggle('is-selected',re);no.setAttribute('aria-expanded',re?'true':'false');}r.querySelector('[data-yes]').addEventListener('click',function(){step('done');dt.textContent='ご協力ありがとうございました';});no.addEventListener('click',function(){if(r.getAttribute('data-step')==='reason'){step('ask');return;}step('reason');setTimeout(function(){ta.focus();},0);});r.querySelector('[data-cancel]').addEventListener('click',function(){step('ask');no.focus();});r.querySelector('.form').addEventListener('submit',function(e){e.preventDefault();step('done');dt.textContent='送信しました。改善に役立てます';});});})();

