(function(){document.querySelectorAll('.p-CONT-01-5').forEach(function(root){if(root.dataset.ready){return;}root.dataset.ready='1';var stage=root.querySelector('.stage');var cards=Array.prototype.slice.call(stage.querySelectorAll('.card'));var cur=root.querySelector('.cur');function update(){var step=cards[0].offsetHeight+(parseFloat(getComputedStyle(cards[0]).marginBottom)||0);if(!step){return;}var idx=Math.min(cards.length-1,Math.floor((stage.scrollTop+stage.clientHeight*0.5)/step));cur.textContent=String(idx+1);cards.forEach(function(c,i){c.classList.toggle('is-under',i<idx);});}stage.addEventListener('scroll',update,{passive:true});update();});})();

