(function(){document.querySelectorAll('.p-CONT-09-3').forEach(function(root){if(root.dataset.ready){return;}root.dataset.ready='1';var form=root.querySelector('.search');var input=root.querySelector('.in');var items=Array.prototype.slice.call(root.querySelectorAll('.item'));var count=root.querySelector('.count');var empty=root.querySelector('.empty');function run(){var q=input.value.trim();var n=0;items.forEach(function(it){var hit=!q||it.textContent.indexOf(q)>-1;it.hidden=!hit;if(hit){n++;}});count.textContent=q?'「'+q+'」の検索結果 '+n+'件':'全'+items.length+'件';empty.hidden=n>0;if(q&&n===1){items.forEach(function(it){if(!it.hidden){it.open=true;}});}}form.addEventListener('submit',function(e){e.preventDefault();run();});input.addEventListener('input',run);root.querySelectorAll('.kw').forEach(function(b){b.addEventListener('click',function(){input.value=b.textContent;run();input.focus();});});});})();

/* CONT-10-1 */
(function(){document.querySelectorAll('.p-CONT-10-1').forEach(function(root){if(root.dataset.ready){return;}root.dataset.ready='1';var box=root.querySelector('.box');var cb=root.querySelector('.cb');var btn=root.querySelector('.btn');var hint=root.querySelector('.hint');function check(){if(cb.disabled&&!btn.dataset.done&&box.scrollHeight>0&&box.scrollTop+box.clientHeight>=box.scrollHeight-4){cb.disabled=false;hint.textContent='全文を確認しました。同意できます';hint.classList.add('is-done');}}box.addEventListener('scroll',check,{passive:true});cb.addEventListener('change',function(){btn.disabled=!cb.checked;});btn.addEventListener('click',function(){btn.dataset.done='1';btn.textContent='同意を受け付けました';btn.disabled=true;cb.disabled=true;});check();});})();

