(function(){document.querySelectorAll('.p-COM-13-1').forEach(function(root){var cards=root.querySelectorAll('.card'),st=root.querySelector('.status');root.addEventListener('click',function(e){var b=e.target.closest('.set');if(!b||!root.contains(b)||b.getAttribute('aria-pressed')==='true')return;var role=b.dataset.role,card=b.closest('.card');cards.forEach(function(c){var on=c===card;c.classList.toggle('is-'+role,on);c.querySelector('.set[data-role='+role+']').setAttribute('aria-pressed',on?'true':'false');});st.textContent='「'+card.querySelector('.lbl').textContent+'」を既定の'+(role==='ship'?'配送先':'請求先')+'にしました';});});})();

