(function(){document.querySelectorAll('.p-COM-13-2').forEach(function(root){var st=root.querySelector('.status');root.querySelectorAll('.addr').forEach(function(it){var ed=it.querySelector('.edit'),f=it.querySelector('.form');function close(){f.hidden=true;ed.setAttribute('aria-expanded','false');ed.focus();}ed.addEventListener('click',function(){var open=f.hidden;f.hidden=!open;ed.setAttribute('aria-expanded',String(open));if(open){st.textContent='';f.querySelector('select').focus();}});f.addEventListener('submit',function(e){e.preventDefault();var s=f.querySelector('select'),r=f.querySelector('input[type=radio]:checked');it.querySelector('[data-k=place]').textContent=s.value;it.querySelector('[data-k=time]').textContent=r.value;Array.prototype.forEach.call(s.options,function(o){o.defaultSelected=o.selected;});f.querySelectorAll('input[type=radio]').forEach(function(x){x.defaultChecked=x.checked;});close();st.textContent='「'+it.dataset.label+'」の配送条件を保存しました';});f.querySelector('.cancel').addEventListener('click',function(){f.reset();close();});f.addEventListener('keydown',function(e){if(e.key==='Escape'){f.reset();close();}});});});})();

