(function(){document.querySelectorAll('.p-COM-17-2').forEach(function(r){var f=r.querySelector('.form'),ty=r.querySelector('.types'),fq=r.querySelector('.freq'),msg=r.querySelector('.msg');function render(){var v=Array.prototype.map.call(f.querySelectorAll('input[type=checkbox]:checked:not(:disabled)'),function(x){return x.value;});if(v.length){ty.textContent=v.join('、');fq.textContent=f.querySelector('input[type=radio]:checked').value;}else{ty.textContent='販促メールは停止中';fq.textContent='—';}}f.addEventListener('submit',function(e){e.preventDefault();render();msg.textContent='設定を保存しました';});f.addEventListener('change',function(){msg.textContent='';});r.querySelector('.all').addEventListener('click',function(){f.querySelectorAll('input[type=checkbox]:not(:disabled)').forEach(function(x){x.checked=false;});render();msg.textContent='すべての販促メールを停止しました';});});})();

/* COM-17-3 */
(function(){var R={freq:['月1回のまとめに変更しました','次回は12月1日にお届けします。'],sale:['セール情報だけに変更しました','新着や読みもののメールは届かなくなります。'],pause:['30日間お休みします','12月11日から配信を再開します。'],all:['すべての配信を停止しました','注文や配送のご連絡のみお送りします。']};document.querySelectorAll('.p-COM-17-3').forEach(function(r){var s=r.querySelectorAll('.stp');function show(i){s.forEach(function(x,j){x.hidden=j!==i;});s[i].querySelector('.h').focus();}function done(k){s[2].querySelector('.h').textContent=R[k][0];s[2].querySelector('.rs').textContent=R[k][1];show(2);}r.querySelector('.alt').addEventListener('submit',function(e){e.preventDefault();done(r.querySelector('.alt input:checked').value);});r.querySelector('.go-all').addEventListener('click',function(){show(1);});r.querySelector('.back').addEventListener('click',function(){show(0);});r.querySelector('.stop').addEventListener('click',function(){done('all');});r.querySelector('.reset').addEventListener('click',function(){show(0);});s[1].addEventListener('keydown',function(e){if(e.key==='Escape')show(0);});});})();
